import{_ as a,o as d,c as e,ai as s}from"./chunks/framework.scx6l_IK.js";const u=JSON.parse('{"title":"问题路径","description":"","frontmatter":{},"headers":[],"relativePath":"30-学习路径/path-问题路径.md","filePath":"30-学习路径/path-问题路径.md","lastUpdated":1778155802000}'),r={name:"30-学习路径/path-问题路径.md"};function n(o,t,h,p,l,i){return d(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="问题路径" tabindex="-1">问题路径 <a class="header-anchor" href="#问题路径" aria-label="Permalink to &quot;问题路径&quot;">​</a></h1><blockquote><p>以问题为导向的学习路径：你遇到什么问题，就从对应的专题入手。 适用人群：带着具体问题来学习的人。</p></blockquote><hr><h2 id="路径总览" tabindex="-1">路径总览 <a class="header-anchor" href="#路径总览" aria-label="Permalink to &quot;路径总览&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你有具体问题吗？</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>选择对应专题（火线入口）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>读原文片段，听原话怎么说的</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>理解背后的核心模型</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>实践方法（每步都有原文依据）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>深入下一个相关问题</span></span></code></pre></div><blockquote><p><strong>整体观提示</strong>：不管从哪个入口进来，先用整体观做一次&quot;三层缩放&quot;——跨时间看因果链、跨立场看各方利益、跨层次看本质。这让你不会只见树木不见森林。详见 <a href="/meta-整体观">整体观元方法</a>。</p></blockquote><hr><h2 id="火线入口-立即解决问题" tabindex="-1">火线入口：立即解决问题 <a class="header-anchor" href="#火线入口-立即解决问题" aria-label="Permalink to &quot;火线入口：立即解决问题&quot;">​</a></h2><p>如果你遇到紧急问题，直接跳到对应的专题。每个专题都配有核心原文片段：</p><table tabindex="0"><thead><tr><th>你的问题</th><th>立即阅读（专题）</th><th>先读这段原文</th></tr></thead><tbody><tr><td><strong>容易紧张、焦虑、担心</strong></td><td><a href="/20-专题研究/topic-焦虑">topic-焦虑</a></td><td><a href="/60-原文段落/金刚经5分-离相">金刚经5分-离相</a> — 焦虑是对未来&quot;相&quot;的执着</td></tr><tr><td><strong>经常生气、悲伤、嫉妒</strong></td><td><a href="/20-专题研究/topic-情绪">topic-情绪</a></td><td><a href="/60-原文段落/金刚经5分-保持平静的要诀">金刚经5分-保持平静的要诀</a> — 理智是操作手柄</td></tr><tr><td><strong>不知道该怎么做决定</strong></td><td><a href="/20-专题研究/topic-选择">topic-选择</a></td><td><a href="/60-原文段落/金刚经3分-攀缘与随缘">金刚经3分-攀缘与随缘</a> — 随缘是根据客观条件做最合理方案</td></tr><tr><td><strong>职场不顺、工作压力大</strong></td><td><a href="/20-专题研究/topic-工作修行">topic-工作修行</a></td><td><a href="/60-原文段落/金刚经1分-修行在生活中">金刚经1分-修行在生活中</a> — 工作单位是道场</td></tr><tr><td><strong>和他人相处困难</strong></td><td><a href="/20-专题研究/topic-人际关系">topic-人际关系</a></td><td><a href="/60-原文段落/金刚经7分-整体观是非对错">金刚经7分-整体观是非对错</a> — 跳出自己立场看全局</td></tr><tr><td><strong>想开始修行但不知从何下手</strong></td><td><a href="/20-专题研究/topic-入门实修">topic-入门实修</a></td><td><a href="/60-原文段落/五篇灵文-温养章全段">五篇灵文-温养章全段</a> — 似守非守，绵绵若存</td></tr><tr><td><strong>生病了、身体不好</strong></td><td><a href="/20-专题研究/topic-疾病与健康">topic-疾病与健康</a></td><td><a href="/60-原文段落/答疑2014-因果分条算">答疑2014-因果分条算</a> — 因果分条算，不抱怨过去的因</td></tr><tr><td><strong>为钱烦恼、对布施不理解</strong></td><td><a href="/20-专题研究/topic-财富与布施">topic-财富与布施</a></td><td><a href="/60-原文段落/金刚经4分-布施的分寸">金刚经4分-布施的分寸</a> — 了解多帮多，不了解少帮</td></tr><tr><td><strong>不知道怎么教育孩子</strong></td><td><a href="/20-专题研究/topic-亲子教育">topic-亲子教育</a></td><td><a href="/60-原文段落/金刚经7分-无为法而有差别">金刚经7分-无为法而有差别</a> — 因材施教，没有固定套路</td></tr><tr><td><strong>被人伤害了、放不下</strong></td><td><a href="/20-专题研究/topic-忍辱与原谅">topic-忍辱与原谅</a></td><td><a href="/60-原文段落/答疑2014-顺逆皆修与冤亲平等">答疑2014-顺逆皆修与冤亲平等</a> — 从恨修到原谅甚至同情</td></tr><tr><td><strong>害怕死亡、亲人离世</strong></td><td><a href="/20-专题研究/topic-生死观">topic-生死观</a></td><td><a href="/60-原文段落/金刚经10分-缘起性空">金刚经10分-缘起性空</a> — 一切不永恒，所以可以改变</td></tr><tr><td><strong>修行遇到瓶颈、想深入</strong></td><td><a href="/20-专题研究/topic-修行进阶">topic-修行进阶</a></td><td><a href="/60-原文段落/金刚经5分-开悟与悟后迷">金刚经5分-开悟与悟后迷</a> — 开悟容易，悟后迷也容易</td></tr></tbody></table><blockquote><p>每个专题 = 具体的分析 + 实操方法 + 原话摘录 + 推荐模型</p></blockquote><hr><h2 id="深度路径-从问题到模型" tabindex="-1">深度路径：从问题到模型 <a class="header-anchor" href="#深度路径-从问题到模型" aria-label="Permalink to &quot;深度路径：从问题到模型&quot;">​</a></h2><p>每个专题背后都有核心模型。当你解决了表面的问题后，建议进一步学习背后的模型。</p><h3 id="路径a-情绪型问题" tabindex="-1">路径A：情绪型问题 <a class="header-anchor" href="#路径a-情绪型问题" aria-label="Permalink to &quot;路径A：情绪型问题&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>情绪/焦虑 ← 对境不住（觉察→不被带跑）</span></span>
<span class="line"><span>                        ↓</span></span>
<span class="line"><span>                  对法不执（连&quot;要平静&quot;的执着也放下）</span></span>
<span class="line"><span>                        ↓</span></span>
<span class="line"><span>                  历境炼心（把每一次情绪波动变成觉悟机会）</span></span></code></pre></div><table tabindex="0"><thead><tr><th>步骤</th><th>做什么</th><th>参考资料</th><th>原文出处</th></tr></thead><tbody><tr><td>A1</td><td>读焦虑/情绪专题，了解情绪的本质</td><td><a href="/20-专题研究/topic-焦虑">topic-焦虑</a>、<a href="/20-专题研究/topic-情绪">topic-情绪</a></td><td><a href="/60-原文段落/金刚经5分-离相">金刚经5分-离相</a></td></tr><tr><td>A2</td><td>学对境不住模型——重点是四步操作法（觉察→暂停→观照→放下）</td><td><a href="/10-核心模型/model-对境不住">model-对境不住</a></td><td><a href="/60-原文段落/金刚经10分-应无所住生心">金刚经10分-应无所住生心</a>、<a href="/60-原文段落/金刚经5分-保持平静的要诀">金刚经5分-保持平静的要诀</a></td></tr><tr><td>A3</td><td>练&quot;理智&quot;操作手柄——情绪起来时问&quot;我为什么不平静？&quot;</td><td>模型原子：理智</td><td><a href="/60-原文段落/金刚经5分-保持平静的要诀">金刚经5分-保持平静的要诀</a></td></tr><tr><td>A4</td><td>学对法不执——连&quot;我必须平静&quot;的执着也放下，不因有情绪而自责</td><td><a href="/10-核心模型/model-对法不执">model-对法不执</a></td><td><a href="/60-原文段落/金刚经6分-法尚应舍">金刚经6分-法尚应舍</a></td></tr><tr><td>A5</td><td>用&quot;烦恼即菩提&quot;转化——这次情绪教了我什么？</td><td><a href="/10-核心模型/model-历境炼心">model-历境炼心</a></td><td><a href="/60-原文段落/金刚经5分-烦恼即菩提">金刚经5分-烦恼即菩提</a></td></tr><tr><td>A6</td><td>从静坐开始建立觉察基础</td><td><a href="/20-专题研究/topic-入门实修">topic-入门实修</a></td><td><a href="/60-原文段落/五篇灵文-温养章全段">五篇灵文-温养章全段</a></td></tr></tbody></table><hr><h3 id="路径b-关系型问题" tabindex="-1">路径B：关系型问题 <a class="header-anchor" href="#路径b-关系型问题" aria-label="Permalink to &quot;路径B：关系型问题&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>人际关系 ← 圆融中和（不偏不倚）</span></span>
<span class="line"><span>                        ↓</span></span>
<span class="line"><span>                  历境炼心（在关系中磨炼）</span></span>
<span class="line"><span>                        ↓</span></span>
<span class="line"><span>                  对境不住（不被对方情绪带跑）</span></span></code></pre></div><table tabindex="0"><thead><tr><th>步骤</th><th>做什么</th><th>参考资料</th><th>原文出处</th></tr></thead><tbody><tr><td>B1</td><td>读人际关系/忍辱专题</td><td><a href="/20-专题研究/topic-人际关系">topic-人际关系</a>、<a href="/20-专题研究/topic-忍辱与原谅">topic-忍辱与原谅</a></td><td><a href="/60-原文段落/答疑2014-顺逆皆修与冤亲平等">答疑2014-顺逆皆修与冤亲平等</a></td></tr><tr><td>B2</td><td>学&quot;离边见&quot;——&quot;他对我错&quot;或&quot;我对他错&quot;都是边见</td><td><a href="/10-核心模型/model-圆融中和">model-圆融中和</a></td><td><a href="/60-原文段落/金刚经1分-离边见">金刚经1分-离边见</a></td></tr><tr><td>B3</td><td>用整体观看关系——站在对方、自己、旁观者三方看同一件事</td><td><a href="/meta-整体观">meta-整体观</a></td><td><a href="/60-原文段落/金刚经7分-整体观是非对错">金刚经7分-整体观是非对错</a></td></tr><tr><td>B4</td><td>练&quot;冤亲平等&quot;——最难修的是对不喜欢的人保持平等心</td><td><a href="/10-核心模型/model-历境炼心">model-历境炼心</a></td><td><a href="/60-原文段落/答疑2014-顺逆皆修与冤亲平等">答疑2014-顺逆皆修与冤亲平等</a></td></tr><tr><td>B5</td><td>学对境不住——对方发火时，你不被带着跑</td><td><a href="/10-核心模型/model-对境不住">model-对境不住</a></td><td><a href="/60-原文段落/金刚经10分-应无所住生心">金刚经10分-应无所住生心</a></td></tr><tr><td>B6</td><td>应用到亲子/家庭关系</td><td><a href="/20-专题研究/topic-亲子教育">topic-亲子教育</a></td><td><a href="/60-原文段落/金刚经7分-无为法而有差别">金刚经7分-无为法而有差别</a></td></tr></tbody></table><hr><h3 id="路径c-行动型问题" tabindex="-1">路径C：行动型问题 <a class="header-anchor" href="#路径c-行动型问题" aria-label="Permalink to &quot;路径C：行动型问题&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>选择困难 ← 自然务实（抓核心、做实事）</span></span>
<span class="line"><span>                        ↓</span></span>
<span class="line"><span>                  圆融中和（不走极端）</span></span>
<span class="line"><span>                        ↓</span></span>
<span class="line"><span>                  对境不住（不被选择焦虑带跑）</span></span></code></pre></div><table tabindex="0"><thead><tr><th>步骤</th><th>做什么</th><th>参考资料</th><th>原文出处</th></tr></thead><tbody><tr><td>C1</td><td>读选择/工作修行专题</td><td><a href="/20-专题研究/topic-选择">topic-选择</a>、<a href="/20-专题研究/topic-工作修行">topic-工作修行</a></td><td><a href="/60-原文段落/金刚经3分-攀缘与随缘">金刚经3分-攀缘与随缘</a></td></tr><tr><td>C2</td><td>学&quot;抓核心&quot;——做决策前问自己&quot;这件事最重要的是什么？&quot;</td><td><a href="/10-核心模型/model-自然务实">model-自然务实</a></td><td><a href="/60-原文段落/金刚经1分-抓住核心">金刚经1分-抓住核心</a></td></tr><tr><td>C3</td><td>练&quot;因上精进，果上随缘&quot;——过程全力以赴，结果怎样都接受</td><td>模型原子：因上精进果上随缘</td><td><a href="/60-原文段落/道德经14章-因上精进果上随缘">道德经14章-因上精进果上随缘</a></td></tr><tr><td>C4</td><td>理解&quot;随缘≠随便&quot;——随缘是从客观条件出发做最合理方案</td><td>模型原子：攀缘vs随缘</td><td><a href="/60-原文段落/金刚经3分-攀缘与随缘">金刚经3分-攀缘与随缘</a></td></tr><tr><td>C5</td><td>学对境不住——不被&quot;选错了怎么办&quot;的念头纠缠</td><td><a href="/10-核心模型/model-对境不住">model-对境不住</a></td><td><a href="/60-原文段落/金刚经18分-三心不可得">金刚经18分-三心不可得</a></td></tr><tr><td>C6</td><td>应用到财富观</td><td><a href="/20-专题研究/topic-财富与布施">topic-财富与布施</a></td><td><a href="/60-原文段落/金刚经4分-布施的分寸">金刚经4分-布施的分寸</a></td></tr></tbody></table><hr><h3 id="路径d-实修型问题" tabindex="-1">路径D：实修型问题 <a class="header-anchor" href="#路径d-实修型问题" aria-label="Permalink to &quot;路径D：实修型问题&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>实修入门 ← 性命双修（身心并重）</span></span>
<span class="line"><span>                        ↓</span></span>
<span class="line"><span>                  对境不住（静坐中的觉察）</span></span>
<span class="line"><span>                        ↓</span></span>
<span class="line"><span>                  天人合一（实修的终极坐标系）</span></span></code></pre></div><table tabindex="0"><thead><tr><th>步骤</th><th>做什么</th><th>参考资料</th><th>原文出处</th></tr></thead><tbody><tr><td>D1</td><td>读入门实修/修行进阶专题</td><td><a href="/20-专题研究/topic-入门实修">topic-入门实修</a>、<a href="/20-专题研究/topic-修行进阶">topic-修行进阶</a></td><td><a href="/60-原文段落/五篇灵文-温养章全段">五篇灵文-温养章全段</a></td></tr><tr><td>D2</td><td>学&quot;神守黄房&quot;——轻轻返观中丹田，这是顿法的直接下手处</td><td><a href="/10-核心模型/model-性命双修">model-性命双修</a></td><td><a href="/60-原文段落/五篇灵文-温养章全段">五篇灵文-温养章全段</a></td></tr><tr><td>D3</td><td>掌握&quot;似守非守&quot;——不可用心守，不可无意求</td><td>模型原子：似守非守</td><td><a href="/60-原文段落/五篇灵文-温养章全段">五篇灵文-温养章全段</a></td></tr><tr><td>D4</td><td>体会&quot;养气忘言守&quot;——养气（命功）和降心（性功）是一件事</td><td>模型原子：养气忘言守</td><td><a href="/60-原文段落/中论丹道-养气忘言守">中论丹道-养气忘言守</a></td></tr><tr><td>D5</td><td>静坐中练对境不住——杂念来了，看着它，不跟随不抵制</td><td><a href="/10-核心模型/model-对境不住">model-对境不住</a></td><td><a href="/60-原文段落/答疑2021-不怕念起只怕觉迟">答疑2021-不怕念起只怕觉迟</a></td></tr><tr><td>D6</td><td>学天人合一——理解实修的终极目标：身体虚无→与宇宙能量场融合</td><td><a href="/10-核心模型/model-天人合一">model-天人合一</a></td><td><a href="/60-原文段落/论坛语录-宇宙统一场">论坛语录-宇宙统一场</a>、<a href="/60-原文段落/答疑2014-箩筐与大海">答疑2014-箩筐与大海</a></td></tr></tbody></table><hr><h3 id="路径e-终极问题" tabindex="-1">路径E：终极问题 <a class="header-anchor" href="#路径e-终极问题" aria-label="Permalink to &quot;路径E：终极问题&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>生死观 ← 天人合一（宇宙观）</span></span>
<span class="line"><span>                        ↓</span></span>
<span class="line"><span>                  对境不住（不被恐惧带跑）</span></span>
<span class="line"><span>                        ↓</span></span>
<span class="line"><span>                  对法不执（放下对生的执着）</span></span></code></pre></div><table tabindex="0"><thead><tr><th>步骤</th><th>做什么</th><th>参考资料</th><th>原文出处</th></tr></thead><tbody><tr><td>E1</td><td>读生死观专题</td><td><a href="/20-专题研究/topic-生死观">topic-生死观</a></td><td><a href="/60-原文段落/金刚经10分-缘起性空">金刚经10分-缘起性空</a></td></tr><tr><td>E2</td><td>理解&quot;缘起性空&quot;——不永恒意味着可以改变，不是消极的&quot;空&quot;</td><td><a href="/10-核心模型/model-天人合一">model-天人合一</a></td><td><a href="/60-原文段落/金刚经10分-缘起性空">金刚经10分-缘起性空</a></td></tr><tr><td>E3</td><td>理解&quot;因果不空&quot;——生命形态会变，但因果相续。你做的好事不会消失</td><td>模型原子：因果不空</td><td><a href="/60-原文段落/金刚经10分-万法皆空因果不空">金刚经10分-万法皆空因果不空</a></td></tr><tr><td>E4</td><td>体会&quot;箩筐与大海&quot;——你不是要变成大海，你本来就是。出无所出</td><td>模型原子：箩筐与大海</td><td><a href="/60-原文段落/答疑2014-箩筐与大海">答疑2014-箩筐与大海</a></td></tr><tr><td>E5</td><td>学对境不住——不被死亡恐惧带跑，知道恐惧也只是三心不可得的&quot;心&quot;</td><td><a href="/10-核心模型/model-对境不住">model-对境不住</a></td><td><a href="/60-原文段落/金刚经18分-三心不可得">金刚经18分-三心不可得</a></td></tr><tr><td>E6</td><td>学对法不执——放下对&quot;生&quot;的执着，但不落断灭见（不是什么都不做）</td><td><a href="/10-核心模型/model-对法不执">model-对法不执</a></td><td><a href="/60-原文段落/金刚经27分-不说断灭相">金刚经27分-不说断灭相</a></td></tr></tbody></table><hr><h2 id="全景图-12个专题的模型支撑" tabindex="-1">全景图：12个专题的模型支撑 <a class="header-anchor" href="#全景图-12个专题的模型支撑" aria-label="Permalink to &quot;全景图：12个专题的模型支撑&quot;">​</a></h2><p>每个专题由哪些核心模型支撑：</p><table tabindex="0"><thead><tr><th>专题</th><th>主模型</th><th>辅模型</th><th>核心原文</th></tr></thead><tbody><tr><td>焦虑</td><td>对境不住</td><td>历境炼心</td><td><a href="/60-原文段落/金刚经5分-离相">金刚经5分-离相</a></td></tr><tr><td>情绪</td><td>对境不住</td><td>对法不执</td><td><a href="/60-原文段落/金刚经5分-保持平静的要诀">金刚经5分-保持平静的要诀</a></td></tr><tr><td>选择</td><td>自然务实</td><td>圆融中和</td><td><a href="/60-原文段落/金刚经3分-攀缘与随缘">金刚经3分-攀缘与随缘</a></td></tr><tr><td>工作修行</td><td>自然务实</td><td>历境炼心</td><td><a href="/60-原文段落/金刚经1分-修行在生活中">金刚经1分-修行在生活中</a></td></tr><tr><td>人际关系</td><td>圆融中和</td><td>历境炼心</td><td><a href="/60-原文段落/金刚经7分-整体观是非对错">金刚经7分-整体观是非对错</a></td></tr><tr><td>入门实修</td><td>性命双修</td><td>对境不住</td><td><a href="/60-原文段落/五篇灵文-温养章全段">五篇灵文-温养章全段</a></td></tr><tr><td>疾病与健康</td><td>天人合一</td><td>对境不住</td><td><a href="/60-原文段落/答疑2014-因果分条算">答疑2014-因果分条算</a></td></tr><tr><td>财富与布施</td><td>对法不执</td><td>自然务实</td><td><a href="/60-原文段落/金刚经4分-布施的分寸">金刚经4分-布施的分寸</a></td></tr><tr><td>亲子教育</td><td>圆融中和</td><td>自然务实</td><td><a href="/60-原文段落/金刚经7分-无为法而有差别">金刚经7分-无为法而有差别</a></td></tr><tr><td>忍辱与原谅</td><td>历境炼心</td><td>对境不住</td><td><a href="/60-原文段落/答疑2014-顺逆皆修与冤亲平等">答疑2014-顺逆皆修与冤亲平等</a></td></tr><tr><td>生死观</td><td>天人合一</td><td>对法不执</td><td><a href="/60-原文段落/金刚经10分-缘起性空">金刚经10分-缘起性空</a></td></tr><tr><td>修行进阶</td><td>性命双修</td><td>历境炼心</td><td><a href="/60-原文段落/金刚经5分-开悟与悟后迷">金刚经5分-开悟与悟后迷</a></td></tr></tbody></table><hr><h2 id="如果专题没解决你的问题" tabindex="-1">如果专题没解决你的问题 <a class="header-anchor" href="#如果专题没解决你的问题" aria-label="Permalink to &quot;如果专题没解决你的问题&quot;">​</a></h2><ol><li><strong>先看原文</strong> → 每个专题都有&quot;核心原文&quot;列——读完原文片段再判断</li><li><strong>试一个模型的完整操作法</strong> → 每个模型页面都有&quot;操作方法&quot;章节，选一个试</li><li><strong>换个入口</strong> → 如果路径A没解决情绪问题，试试路径C（行动）——有时情绪的根源是不知道怎么行动</li><li><strong>用整体观三层缩放</strong> → 跨时间（这件事十年后还重要吗？）、跨立场（对方怎么看？）、跨层次（从更高层面看，什么最重要？）</li></ol><hr><blockquote><p>创建日期：2026-05-06 | 修订：2026-05-07（火线入口+原文片段列；5条深度路径各新增6步操作表+每步原文出处；全景图重构为专题-模型-原文对照表；新增整体观提示；新增&quot;没解决怎么办&quot;指引）</p></blockquote>`,42)])])}const f=a(r,[["render",n]]);export{u as __pageData,f as default};
